@CrossOrigin
@RestController
@RequestMapping("/ShipmentQuery")
public class ShipmentQueryRestController extends BaseSpringRestController {
	
	public ShipmentQueryRestController( ShipmentService service ) {
        this.service = service;
    }
    
    /**
     * Handles loading a Shipment using a UUID
     * @param		UUID shipmentId
     * @return		Shipment
     */    
    @GetMapping("/load")
    public Shipment load( @RequestParam(required=true) UUID shipmentId ) {
    	Shipment entity = null;

    	try {  
    		entity = service.getShipment( new ShipmentFetchOneSummary( shipmentId ) );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING, "failed to load Shipment using Id " + shipmentId );
            return null;
        }

        return entity;
    }

    /**
     * Handles loading all Shipment business objects
     * @return		Set<Shipment>
     */
    @GetMapping("/")
    public List<Shipment> loadAll() {                
    	List<Shipment> shipmentList = null;
        
    	try {
            // load the Shipment
            shipmentList = service.getAllShipment();
            
            if ( shipmentList != null )
                LOGGER.log( Level.INFO,  "successfully loaded all Shipments" );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING,  "failed to load all Shipments ", exc );
        	return null;
        }

        return shipmentList;
                            
    }



//************************************************************************    
// Attributes
//************************************************************************
    protected Shipment shipment = null;
    protected ShipmentService service = null;
    private static final Logger LOGGER = Logger.getLogger(ShipmentQueryRestController.class.getName());
    
}
